// Title: Export a worksheet to PNG and validate file size and .png extension with Aspose.Cells for .NET (C#)
// Common Searches: how to render an Excel worksheet to a PNG file using Aspose.Cells in C# | C# code to ensure exported PNG from Aspose.Cells is not empty | verify the file extension of an image generated by SheetRender in Aspose.Cells | example of using ImageOrPrintOptions OnePagePerSheet for PNG export | check PNG output after converting an Excel sheet with Aspose.Cells .NET
// Tags: Aspose.Cells worksheet to PNG export | ImageOrPrintOptions PNG configuration | SheetRender ToImage validation | C# verify exported image file size | C# check PNG file extension Aspose.Cells

using System;
using System.IO;
using Aspose.Cells;
using Aspose.Cells.Rendering; // For ImageOrPrintOptions and SheetRender

// The sample loads an Excel workbook, sets ImageOrPrintOptions (including OnePagePerSheet), renders the first worksheet to a PNG file with SheetRender, then confirms the PNG file exists, is non‑empty, and has a .png extension, reporting success or errors.
class Program
{
    static void Main()
    {
        try
        {
            // Path to the source Excel file
            string excelPath = "input.xlsx";

            // Verify that the input file exists
            if (!File.Exists(excelPath))
            {
                Console.WriteLine($"Error: Excel file \"{excelPath}\" not found.");
                return;
            }

            // Path where the PNG will be saved
            string pngPath = "output.png";

            // Load the workbook
            Workbook workbook = new Workbook(excelPath);

            // Set image export options (default format is PNG)
            ImageOrPrintOptions options = new ImageOrPrintOptions
            {
                // If a specific format is required, uncomment the line below and ensure the enum exists in your Aspose.Cells version.
                // ImageFormat = ImageFormat.Png
                OnePagePerSheet = true // Example additional option
            };

            // Render the first worksheet to a PNG file
            SheetRender sheetRender = new SheetRender(workbook.Worksheets[0], options);
            sheetRender.ToImage(0, pngPath);

            // Validate that the PNG file was created
            if (!File.Exists(pngPath))
            {
                Console.WriteLine("Error: PNG file was not created.");
                return;
            }

            // Basic validation of file size and extension
            FileInfo info = new FileInfo(pngPath);
            if (info.Length == 0)
            {
                Console.WriteLine("Validation failed: PNG file is empty.");
                return;
            }

            if (!string.Equals(info.Extension, ".png", StringComparison.OrdinalIgnoreCase))
            {
                Console.WriteLine("Validation failed: File extension is not .png.");
                return;
            }

            Console.WriteLine("PNG validation succeeded. File created successfully.");
        }
        catch (Exception ex)
        {
            Console.WriteLine($"An unexpected error occurred: {ex.Message}");
        }
    }
}
